def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Repeated motifs have a three-cell blank tail; mark that tail on
    # repeated rows when the motif reaches its rightmost template cell.
    tail = min(3, w - 1)
    prefix = w - tail
    for r in range(h):
        if all(grid[r][c] == bg for c in range(prefix, w)):
            if grid[r][prefix - 1] == bg:
                continue
            if any(grid[q][:prefix] == grid[r][:prefix] for q in range(r)):
                for c in range(prefix, w):
                    out[r][c] = 1

    # A shorter solid stripe matching a full-width stripe is marked
    # across its missing continuation.
    for r, row in enumerate(grid):
        colors = [v for v in row if v != bg]
        if not colors or len(set(colors)) != 1:
            continue
        color = colors[0]
        end = max(c for c, v in enumerate(row) if v == color)
        if end == w - 1:
            continue
        if any(all(v == color for v in other) for other in grid):
            for c in range(end + 1, w):
                out[r][c] = 1

    return out
